pub(in crate::time::calendar) fn austria_settlement(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            // Epiphany
            || (d == 6 && m == 1)
            // Easter Monday
            || (dd == em)
            // Ascension Thurday 
            || (dd == em+38)
            // Whit Monday
            || (dd == em+49)
            // Corpus Christi
            || (dd == em+59)
            // Labour Day
            || (d == 1 && m == 5)
            // Assumption
            || (d == 15 && m == 8)
            // National Holiday since 1967
            || (d == 26 && m == 10 && y >= 1967)
            // National Holiday 1919-1934
            || (d == 12 && m == 11 && y >= 1919 && y <= 1934)
            // All Saints' Day
            || (d == 1 && m == 11)
            // Immaculate Conception
            || (d == 8 && m == 12)
            // Christmas
            || (d == 25 && m == 12)
            // St. Stephen
            || (d == 26 && m == 12)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn austria_exchange(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            // Good Friday
            || (dd == em-3)
            // Easter Monday
            || (dd == em)
            // Whit Monay
            || (dd == em+49)
            // Labour Day
            || (d == 1 && m == 5)
            // National Holiday since 1967
            || (d == 26 && m == 10 && y >= 1967)
            // National Holiday 1919-1934
            || (d == 12 && m == 11 && y >= 1919 && y <= 1934)
            // Christmas' Eve
            || (d == 24 && m == 12)
            // Christmas
            || (d == 25 && m == 12)
            // St. Stephen
            || (d == 26 && m == 12)
            // Exchange Holiday
            || (d == 31 && m == 12)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn czech_republic_pse(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            // Good Friday
            || (dd == em - 3 && y >= 2016)
            // Easter Monday
            || (dd == em)
            // Labour Day
            || (d == 1 && m == 5)
            // Liberation Day
            || (d == 8 && m == 5)
            // SS. Cyril and Methodius
            || (d == 5 && m == 7)
            // Jan Hus Day
            || (d == 6 && m == 7)
            // Czech Statehood Day
            || (d == 28 && m == 9)
            // Independence Day
            || (d == 28 && m == 10)
            // Struggle for Freedom and Democracy Day
            || (d == 17 && m == 11)
            // Christmas Eve
            || (d == 24 && m == 12)
            // Christmas
            || (d == 25 && m == 12)
            // St. Stephen
            || (d == 26 && m == 12)
            // unidentified closing days for stock exchange
            || (d == 2 && m == 1 && y == 2004)
            || (d == 31 && m == 12 && y == 2004)
    {
        return false;
    }

    true
}

